package org.springframework.samples.petclinic.util;

import java.util.Collection;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;

/**
 * Derives an owner's {@code identityKey}: {@code normalizedTelephone|email|householdId}.
 * All duplicate detection is consolidated here: two owners are the same registration only
 * when their WHOLE identity keys are equal, and a new owner is rejected only on a full match.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    /**
     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. An owner carries no
     * shared-household membership in its stored state, so the household component is empty and two
     * owners differ in identity only through their telephone and email.
     */
    public static String of(Owner owner) {
        return telephone(owner.getTelephone()) + "|" + email(owner.getEmail()) + "|";
    }

    /** Reject with 409 when {@code candidate}'s whole identity key equals an existing owner's. */
    public static void rejectIfDuplicate(Owner candidate, Collection<Owner> existingOwners) {
        String key = of(candidate);
        for (Owner owner : existingOwners) {
            if (key.equals(of(owner))) {
                throw new DuplicateTelephoneException(key);
            }
        }
    }

    /** Digits only, so equality ignores telephone formatting differences. */
    private static String telephone(String telephone) {
        return telephone == null ? "" : telephone.replaceAll("\\D", "");
    }

    /** Lower-cased and trimmed, so equality ignores case; blank/absent emails compare equal. */
    private static String email(String email) {
        return email == null ? "" : email.trim().toLowerCase(Locale.ROOT);
    }
}
=== Namesakes ===
package org.springframework.samples.petclinic.util;

import java.util.Collection;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Counts how many existing owners share a candidate owner's first and last name,
 * compared case-insensitively (the {@code namesakeCount}).
 */
public final class Namesakes {

    private Namesakes() {
    }

    public static int count(Owner candidate, Collection<Owner> existing) {
        int namesakes = 0;
        for (Owner other : existing) {
            if (candidate.getFirstName().equalsIgnoreCase(other.getFirstName())
                && candidate.getLastName().equalsIgnoreCase(other.getLastName())) {
                namesakes++;
            }
        }
        return namesakes;
    }
}
=== GoldTier ===
package org.springframework.samples.petclinic.util;

import java.util.Collection;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Decides the GOLD membership tier: an owner qualifies once their household (owners
 * sharing the same {@link Household} id, i.e. the same normalized last name and
 * address) has three or more members. When it does not apply, the mapper's existing
 * BRONZE/SILVER rules stand.
 */
public final class GoldTier {

    private GoldTier() {
    }

    /** True when {@code owner}'s household has 3+ members among {@code allOwners}. */
    public static boolean qualifies(Owner owner, Collection<Owner> allOwners) {
        String household = Household.idFor(owner.getLastName(), owner.getAddress());
        return allOwners.stream()
            .filter(o -> household.equals(Household.idFor(o.getLastName(), o.getAddress())))
            .count() >= 3;
    }
}

